 async list(){const q=new URLSearchParams(location.search),query=new URLSearchParams({page:q.get('page')||1,status:q.get('status')||'',work_status:q.get('work_status')||''}),d=await API.request('/cobalt/sales-workflow/preparations?'+query),t=this.t,s=d.summary,cards=[['待提交','Draft',s.draft,'status=DRAFT'],['备货作业中','Preparation',s.preparing,'work_status=PREPARING'],['待现场主管审核','Site Review',s.site_pending,'work_status=PENDING_COMPLETION_REVIEW'],['待生产经理确认入库','Final Receipt Review',s.production_pending,'status=PRODUCTION_PENDING'],['已正式入库','Formally Received',s.received,'status=RECEIVED']];Router.page(t('入库与备货管理','Receipts and Preparation'),'<div class="co-intake-unified"><div class="v34-kpi-grid">'+cards.map(([z,e,n,url])=>'<a class="v34-kpi" href="/receipts?'+url+'"><span>'+t(z,e)+'</span><strong>'+n+'</strong></a>').join('')+'</div><div class="business-toolbar">'+(CurrentUser.permissions.includes('co:create')?'<a class="button primary" href="/receipts/new">'+t('新建入库备货单','New Receipt and Preparation')+'</a>':'')+'</div><p>'+t('同一张单据贯穿提交、入库审核、备货作业及完工审核，统一查询和办理。','One document covers submission, receipt review, preparation and completion review.')+'</p><form id="co-intake-filter" class="filters" data-v34-reset="true"><div class="form-grid"><label>'+t('入库状态','Receipt Status')+'<select name="status"><option value="">'+t('全部','All')+'</option>'+Object.keys(CobaltUI.states).map(x=>'<option value="'+x+'" '+(q.get('status')===x?'selected':'')+'>'+CobaltUI.status(x)+'</option>').join('')+'</select></label><label>'+t('备货状态','Preparation Status')+'<select name="work_status"><option value="">'+t('全部','All')+'</option>'+['PREPARING','PENDING_COMPLETION_REVIEW','COMPLETED'].map(x=>'<option value="'+x+'" '+(q.get('work_status')===x?'selected':'')+'>'+CobaltWorkUI.status(x)+'</option>').join('')+'</select></label></div><div class="business-toolbar"><button class="button secondary">'+t('查询','Search')+'</button><a class="button secondary" href="/receipts">'+t('重置筛选','Reset Filters')+'</a></div></form>'+CobaltSalesUI.table([['入库备货单号','Receipt / Preparation No.'],['备货批次','Preparation Batch'],['业务日期','Business Date'],['袋数','Bags'],['入库状态','Receipt Status'],['备货状态','Preparation Status'],['操作','Actions']],d.items.map(p=>p.historical_import?'<tr><td><a data-no-i18n href="'+esc(p.href)+'">'+esc(p.document_no)+'</a></td><td data-no-i18n>'+esc(p.preparation_batch_no)+'</td><td>'+esc(p.planned_load_day)+'</td><td>'+p.bag_count+'</td><td>'+CobaltUI.status(p.status)+'</td><td>—</td><td><a class="button secondary compact" href="'+esc(p.href)+'">'+t('详情','Details')+'</a></td></tr>':'<tr><td><a data-no-i18n href="/receipts/'+p.id+'">'+esc(p.document_no)+'</a></td><td data-no-i18n>'+esc(p.preparation_batch_no)+'</td><td>'+esc(p.business_date)+'</td><td>'+p.bag_count+'</td><td>'+CobaltUI.status(p.status)+'</td><td>'+(p.work_status&&p.work_status!==p.status&&CobaltWorkUI.status(p.work_status)!==CobaltUI.status(p.status)?CobaltWorkUI.status(p.work_status):'—')+'</td><td><a class="button secondary compact" href="/receipts/'+p.id+'">'+t('详情 / 入库审核','Details / Receipt Review')+'</a>'+(p.work_status?' <a class="button secondary compact" href="/receipts/'+p.id+'/work">'+t(p.work_status==='COMPLETED'?'查看备货':'备货作业 / 审核',p.work_status==='COMPLETED'?'View Preparation':'Preparation / Review')+'</a>':'')+'</td></tr>'),'co-intake-table')+CobaltStockUI.pager(d.page,d.total,d.page_size)+'</div>');$('co-intake-table').dataset.v34Server='true';$('co-intake-filter').onsubmit=e=>{e.preventDefault();Router.go('/receipts?'+new URLSearchParams(new FormData(e.target)));};CobaltStockUI.bindPager(d);ProductContext.dirty=false;}
