window.CobaltCount={
 t:CobaltIntake.t,base:'/cobalt/stocktaking',can:p=>CurrentUser.permissions.includes(p),
 status(s){return this.t(...({OPEN:['清点中','Counting'],SUBMITTED:['待复核','Awaiting Review'],APPROVED:['已复核归档','Reviewed and Archived'],REJECTED:['退回清点','Returned for Recount'],CANCELLED:['已取消','Cancelled']}[s]||[s,s]));},
 error(e){const key=Object.keys(this.errors).find(k=>(e.message||'').includes(k));return key?this.t(...this.errors[key]):e.message;},errors:{CO_COUNT_PERMISSION:['当前账号没有盘点操作权限','This account has no counting permission'],CO_COUNT_SCOPE:['盘点对象不在授权项目或仓库范围','The count is outside your project or warehouse scope'],CO_COUNT_STALE:['单据已变化，请保留输入并刷新核对','The count changed. Keep inputs and refresh to verify'],CO_COUNT_INCOMPLETE:['本轮仍有未清点袋号，请完成后提交','Finish counting all bags in this round before submitting'],CO_COUNT_STOCK_CHANGED:['盘点期间库存、位置或备货资料已变化，请刷新基准并重新清点；原轮次保留','Inventory, location or preparation changed. Refresh the baseline and recount; previous rounds are retained'],CO_COUNT_INDEPENDENT_REVIEW:['驳回须填写至少5字原因','Review requires authorization who did not create, submit or count. Give at least 5 characters when rejecting'],CO_COUNT_STATE:['当前状态不允许此操作','This action is unavailable in the current state'],CO_COUNT_INPUT:['请核对袋号、位置、重量及备注','Check the bag, location, weight and note'],CO_COUNT_NOT_FOUND:['盘点单不存在或不在授权范围','Count not found or outside your scope']},
 async list(){return StocktakeList.list(true);},
 async create(){const o=await API.request(this.base+'/options'),t=this.t;this.options=o;Router.page(t('新建氢氧化钴盘点','New Cobalt Stocktake'),'<form id="co-count-create" class="user-form">'+StocktakeList.creationFields(true)+'<label>'+t('任务名称','Title')+'<input name="title" required maxlength="160"></label><label>'+t('仓库','Warehouse')+'<select name="warehouse_id" required>'+o.warehouses.map(w=>'<option value="'+w.id+'">'+esc(I18n.translate(w.name,true))+'</option>').join('')+'</select></label><p>'+t('建立当前在库袋的独立快照，包括备货及已装车待正式出库的库存。','Create an independent snapshot of current bags, including preparation and loaded stock awaiting formal outbound.')+'</p><p class="error" id="co-count-error" role="alert"></p><button class="button primary">'+t('创建盘点任务','Create Stocktake')+'</button></form>');StocktakeList.bindCreation($('co-count-create'));$('co-count-create').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const b=Object.fromEntries(new FormData(e.target)),w=o.warehouses.find(w=>w.id===b.warehouse_id);if(!w)throw Error(t('请选择授权仓库','Select an authorized warehouse'));const r=await API.request(this.base,{method:'POST',body:{...b,project_id:w.project_id}});ProductContext.dirty=false;await Router.go('/stocktaking/'+r.id);}catch(err){$('co-count-error').textContent=this.error(err);e.submitter.disabled=false;}};ProductContext.dirty=false;},
 isEditing(){return !!($('co-count-create')||$('co-count-record'));},
 async detail(id){const q=new URLSearchParams(location.search),[d,o]=await Promise.all([API.request(this.base+'/'+id+'?page='+(q.get('page')||1)),API.request(this.base+'/options')]),t=this.t,p=d.task,s=d.summary,edit=this.can('stocktake:write')&&['OPEN','REJECTED'].includes(p.status);this.data=d;this.options=o;this.expected=p.version;
 Router.page(t('氢氧化钴盘点详情','Cobalt Stocktake Details'),'<div class="co-count-page"><h2 data-no-i18n>'+esc(p.code+' · '+p.title)+'</h2><p>'+this.status(p.status)+' · '+t('轮次','Round')+' '+p.round+' · '+esc(I18n.translate(p.warehouse_name,true))+'</p><p>'+t('基准时间','Baseline Time')+'：'+BusinessTime.display(d.round.cutoff_at)+'</p><div class="v34-kpi-grid">'+[[t('账面袋数','Expected Bags'),s.expected],[t('已清点袋数','Counted Bags'),s.observed],[t('实物找到','Found'),s.found],[t('实物未找到','Missing'),s.missing],[t('差异项','Differences'),s.differences],[t('未实测重量','Unmeasured Weight'),s.unconfirmed_weights]].map(([k,v])=>'<article class="v34-kpi"><span>'+k+'</span><strong>'+v+'</strong></article>').join('')+'</div>'+(d.stock_changed&&p.status!=='APPROVED'?'<p class="error">'+this.t(...this.errors.CO_COUNT_STOCK_CHANGED)+'</p>':'')+'<p>'+t('重量留空代表未实测；复核报告不自动扣减或增加库存。','Blank weight means unmeasured. A reviewed report does not automatically deduct or add inventory.')+'</p><form id="co-count-record" class="user-form"><fieldset '+(edit?'':'disabled')+'>'+CobaltSalesUI.table([['袋号 / 批次','Bag / Batch'],['账面位置','Book Location'],['实盘结果','Observation'],['实盘位置','Observed Location'],['实测毛重（kg）','Measured Gross (kg)'],['备注','Note']],d.items.map(x=>'<tr data-count-bag="'+x.book.bag_id+'"><td data-no-i18n>'+esc(x.book.bag_no)+'<br>'+esc(x.book.batch_no)+'</td><td data-no-i18n>'+esc(x.book.location_code||'—')+'</td><td><select data-present><option value="">'+t('未清点','Not Counted')+'</option><option value="true" '+(x.observation_id&&x.present?'selected':'')+'>'+t('实物找到','Found')+'</option><option value="false" '+(x.observation_id&&!x.present?'selected':'')+'>'+t('实物未找到','Missing')+'</option></select></td><td><select data-location><option value="">'+t('未定位','Unlocated')+'</option>'+o.locations.filter(l=>l.warehouse_id===p.warehouse_id).map(l=>'<option value="'+l.id+'" '+((x.observation_id?x.actual_location_id:x.book.location_id)===l.id?'selected':'')+'>'+esc(l.code)+'</option>').join('')+'</select></td><td><input data-gross inputmode="decimal" value="'+esc(x.actual_gross_kg||'')+'" placeholder="'+t('未实测','Unmeasured')+'"></td><td><input data-note maxlength="1000" value="'+esc(x.note||'')+'"></td></tr>'),'co-count-items')+(edit?'<div class="business-toolbar"><button type="button" id="co-count-found" class="button secondary">'+t('本页实物确认在位（重量另填）','Confirm Current Page Found (Weights Separate)')+'</button><button class="button primary">'+t('保存本页实盘','Save Page Observations')+'</button></div>':'')+'</fieldset></form><p id="co-count-error" class="error" role="alert"></p>'+CobaltStockUI.pager(d.page,d.total,d.page_size)+'<div class="business-toolbar">'+(edit?'<button class="button primary" data-count-action="submit">'+t('提交复核','Submit for Review')+'</button><button class="button secondary" data-count-action="refresh">'+t('刷新基准，开启新轮次','Refresh Baseline and Start New Round')+'</button><button class="button secondary" data-count-action="cancel">'+t('取消任务','Cancel Count')+'</button>':'')+(p.status==='SUBMITTED'&&this.can('stocktake:review')?'<button class="button primary" data-count-action="approve">'+t('复核通过并归档','Review and Archive')+'</button><button class="button secondary" data-count-action="reject">'+t('驳回重新清点','Return for Recount')+'</button>':'')+'<a class="button secondary" href="/stocktaking">'+t('返回盘点管理','Back to Stocktaking')+'</a></div><h3>'+t('操作历史','History')+'</h3>'+d.history.map(h=>'<p data-no-i18n>'+esc(BusinessTime.display(h.occurred_at)+' · '+h.actor_name+' · '+h.action+' · '+h.note)+'</p>').join('')+'</div>');
 if($('co-count-found'))$('co-count-found').onclick=()=>{for(const row of document.querySelectorAll('[data-count-bag]'))row.querySelector('[data-present]').value='true';ProductContext.dirty=true;};$('co-count-record').onsubmit=async e=>{e.preventDefault();if(!edit)return;const items=[...document.querySelectorAll('[data-count-bag]')].filter(row=>row.querySelector('[data-present]').value!=='').map(row=>({bag_id:row.dataset.countBag,present:row.querySelector('[data-present]').value==='true',actual_location_id:row.querySelector('[data-location]').value||null,actual_gross_kg:row.querySelector('[data-gross]').value||null,note:row.querySelector('[data-note]').value}));try{await API.request(this.base+'/'+id+'/observe',{method:'POST',body:{version:this.expected,items}});ProductContext.dirty=false;await this.detail(id);}catch(err){$('co-count-error').textContent=this.error(err);}};
 for(const b of document.querySelectorAll('[data-count-action]'))b.onclick=async()=>{const action=b.dataset.countAction;let note='';if(!await OperationConfirm.ask({title:b.textContent,rows:[[t('盘点单号','Count No.'),p.code],[t('账面 / 已清点','Expected / Counted'),s.expected+' / '+s.observed]],note:action==='refresh'?t('原轮次保留，新轮次须重新清点。','Previous rounds remain; the new round requires recounting.'):t('本操作保存盘点报告，不调整实物库存。','This action records the count without adjusting physical inventory.'),comment:true,commentRequired:['refresh','reject','cancel'].includes(action),onComment:v=>note=v}))return;try{await API.request(this.base+'/'+id+'/'+action,{method:'POST',body:{version:this.expected,note}});ProductContext.dirty=false;await this.detail(id);}catch(err){$('co-count-error').textContent=this.error(err);}};CobaltStockUI.bindPager(d);ProductContext.dirty=false;const latest=[...d.history].reverse().find(h=>h.action==='observe');BusinessWorkflow.place(BusinessWorkflow.render([{title:t('建立基准','Baseline'),person:p.creator_name},{title:t('袋级实盘','Bag Counting'),person:latest?.actor_name||t('盘点人员','Counter')},{title:t('复核','Review'),person:p.reviewer_name||t('复核人','Reviewer')},{title:t('报告归档','Report Archived'),person:p.status==='APPROVED'?p.reviewer_name:''}],{rank:p.status==='APPROVED'?3:['SUBMITTED','REJECTED'].includes(p.status)?2:1,rejected:p.status==='REJECTED',label:p.status==='CANCELLED'?t('已取消','Cancelled'):''}));
 },
 async language(){const create=$('co-count-create'),record=$('co-count-record'),dirty=ProductContext.dirty,version=this.expected,saved=create?Object.fromEntries(new FormData(create)):record?[...document.querySelectorAll('[data-count-bag]')].map(row=>({id:row.dataset.countBag,values:[...row.querySelectorAll('input,select')].map(x=>x.value)})):null;if(create)await this.create();else if(record)await this.detail(this.data.task.id);if(create&&saved)for(const [k,v]of Object.entries(saved))if($('co-count-create').elements[k])$('co-count-create').elements[k].value=v;if(record&&saved)for(const x of saved){const row=document.querySelector('[data-count-bag="'+x.id+'"]');if(row)[...row.querySelectorAll('input,select')].forEach((e,i)=>e.value=x.values[i]);}if(dirty)this.expected=version;ProductContext.dirty=dirty;}
};
